package pizza.customer;

import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import javax.sql.DataSource;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import java.util.Optional;

/**
 * Uses the {@link JdbcClient} (since Spring 6.1) -- a fluent alternative to the {@code JdbcTemplate}
 * with named parameters. The id of a new customer is generated by the database.
 */
@Repository
public class JdbcCustomerRepository implements CustomerRepository {

    public static final String INSERT_SQL = """
            INSERT INTO customers (full_name, phone_number, street, postal_code, city)
            VALUES (:fullName, :phoneNumber, :street, :postalCode, :city)""";
    public static final String SELECT_ALL_SQL = "SELECT c.* FROM customers c ORDER BY c.id";
    public static final String SELECT_BY_PHONE_NUMBER_SQL = "SELECT c.* FROM customers c WHERE c.phone_number = :phoneNumber";

    private final JdbcClient jdbcClient;
    private final RowMapper<Customer> rowMapper;

    public JdbcCustomerRepository(DataSource dataSource) {
        this.jdbcClient = JdbcClient.create(dataSource);
        this.rowMapper = new CustomerRowMapper();
    }

    @Override
    public Customer save(Customer customer) {
        Address address = customer.getAddress();
        KeyHolder keyHolder = new GeneratedKeyHolder();
        this.jdbcClient.sql(INSERT_SQL)
                .param("fullName", customer.getFullName())
                .param("phoneNumber", customer.getPhoneNumber())
                .param("street", address != null ? address.getStreet() : null)
                .param("postalCode", address != null ? address.getPostalCode() : null)
                .param("city", address != null ? address.getCity() : null)
                .update(keyHolder, "id");
        customer.setId(keyHolder.getKeyAs(Long.class));
        return customer;
    }

    @Override
    public List<Customer> findAll() {
        return this.jdbcClient.sql(SELECT_ALL_SQL)
                .query(this.rowMapper)
                .list();
    }

    @Override
    public Optional<Customer> findByPhoneNumber(String phoneNumber) {
        return this.jdbcClient.sql(SELECT_BY_PHONE_NUMBER_SQL)
                .param("phoneNumber", phoneNumber)
                .query(this.rowMapper)
                .optional();
    }

    //
    // --- inner classes ---
    //

    static class CustomerRowMapper implements RowMapper<Customer> {
        @Override
        public Customer mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new Customer(
                    rs.getLong("id"),
                    rs.getString("full_name"),
                    new Address(
                            rs.getString("street"),
                            rs.getString("postal_code"),
                            rs.getString("city")
                    ),
                    rs.getString("phone_number")
            );
        }
    }
}
